class TestAix(unittest.TestCase):
    def test_basic_parse(self):
        contract = {"name": "aix", "operation": "aix_parse", "inputs": ["x"]}
        payload = {"aix": "/data:\n  dev = /dev/aix\n  options = rw\n/backup:\n  dev = /dev/b\n"}
        result = transform([payload], contract)
        self.assertEqual(set(result), {"name", "result"})
        self.assertEqual(result["name"], "aix")
        records = result["result"]["records"]
        self.assertEqual(len(records), 2)
        self.assertEqual(records[0]["mount"], "/data")
        self.assertEqual(records[0]["device"], "/dev/aix")
        self.assertEqual(records[0]["fstype"], "jfs2")
        self.assertEqual(records[0]["options"], ["rw"])
        self.assertEqual(records[1]["mount"], "/backup")
        self.assertEqual(records[1]["device"], "/dev/b")
        self.assertEqual(records[1]["fstype"], "jfs2")
        self.assertEqual(records[1]["options"], ["rw"])

    def test_missing_dev(self):
        contract = {"name": "aix", "operation": "aix_parse", "inputs": ["x"]}
        payload = {"aix": "/data:\n  options = rw\n"}
        with self.assertRaises(ValueError):
            transform([payload], contract)

    def test_duplicate_key(self):
        contract = {"name": "aix", "operation": "aix_parse", "inputs": ["x"]}
        payload = {"aix": "/data:\n  dev = /dev/a\n  dev = /dev/b\n"}
        with self.assertRaises(ValueError):
            transform([payload], contract)

    def test_unknown_key(self):
        contract = {"name": "aix", "operation": "aix_parse", "inputs": ["x"]}
        payload = {"aix": "/data:\n  dev = /dev/a\n  foo = bar\n"}
        with self.assertRaises(ValueError):
            transform([payload], contract)

    def test_load_payload_rejects_scalar(self):
        import tempfile
        with tempfile.NamedTemporaryFile("w", suffix=".json", delete=False) as f:
            f.write("42")
            p = f.name
        with self.assertRaises(ValueError):
            load_payload(p)


if __name__ == "__main__":
    unittest.main()

