            "mount": current["mount"],
            "fstype": current.get("vfs", "jfs2"),
            "options": _parse_options(current.get("options", "rw")),
        })
        current = None

    for raw_line in text.splitlines():
        line = raw_line.strip()
        if line == "" or line.startswith("#"):
            continue
        if line.endswith(":"):
